{
  "recorte_destino": "F05",
  "titulo": "Amostragem, medição de TOG, tratamento e controle do descarte de água produzida",
  "base_blocos": [
    "F05-V01-B001",
    "F05-V02-B002",
    "F05-V02-B003",
    "F05-V02-B005",
    "F05-V02-B006"
  ],
  "sintese_tecnica": [
    {
      "topico": "O que é água produzida e por que ela precisa de controle",
      "conteudo": "Água produzida é a corrente aquosa separada do petróleo e do gás durante o processamento primário. Mesmo após a separação do óleo, ela ainda pode conter gás carbônico, sulfídrico, óleo remanescente, sólidos em suspensão, produtos de corrosão, incrustações, sais, metais e compostos orgânicos dissolvidos ou dispersos. Por isso, antes da destinação, ela normalmente requer tratamento e monitoramento."
    },
    {
      "topico": "Escopo regulatório preservado",
      "conteudo": "Nos trechos citados, o enquadramento regulatório tratado refere-se ao descarte contínuo em plataformas marítimas de petróleo e gás natural. Esse escopo não deve ser transferido automaticamente para operações onshore ou para outros tipos de empreendimento."
    },
    {
      "topico": "Centralidade do TOG no descarte offshore",
      "conteudo": "No descarte contínuo em plataformas marítimas, o teor de óleos e graxas (TOG) aparece como parâmetro central de controle ambiental nas regras brasileiras citadas, com controle por média temporal e por valor máximo diário. Isso não significa que o TOG esgote sozinho a avaliação ambiental da água produzida."
    },
    {
      "topico": "Outros parâmetros relevantes",
      "conteudo": "Além do TOG, os trechos citam monitoramento e caracterização de compostos inorgânicos, radioisótopos, compostos orgânicos, toxicidade crônica e parâmetros complementares como carbono orgânico total, pH, salinidade, temperatura e nitrogênio amoniacal total. Assim, o controle do descarte combina um parâmetro central de enquadramento com uma caracterização ambiental mais ampla."
    },
    {
      "topico": "Formas de ocorrência do óleo na água",
      "conteudo": "O material orgânico/óleo na água produzida pode estar tanto na forma dispersa quanto dissolvida. Essa distinção é tecnicamente importante porque diferentes formas de ocorrência tendem a responder de modo diferente ao tratamento e à medição."
    },
    {
      "topico": "Objetivo do tratamento",
      "conteudo": "Os sistemas de tratamento de água oleosa citados buscam remover óleo livre ou disperso e sólidos em suspensão antes do descarte. É comum a aplicação de produtos químicos para quebra de emulsões."
    },
    {
      "topico": "Arranjos de tratamento citados",
      "conteudo": "Um arranjo consagrado em unidades offshore é a combinação em série de hidrociclones e flotadores. Em alguns casos, a bateria de hidrociclones pode ser suficiente para enquadramento do efluente, mas os trechos disponíveis não detalham os critérios operacionais que condicionam esse resultado."
    },
    {
      "topico": "Como a distribuição do óleo afeta a remoção",
      "conteudo": "A redução do TOG depende de como o óleo está distribuído na água. Quando o óleo está em gotas mais facilmente separáveis, processos físicos tendem a ser mais eficazes. Quando está finamente disperso, emulsificado ou associado a sólidos, a remoção física tende a se tornar mais difícil. A adição de produtos químicos para quebra de emulsões pode modificar essa separabilidade."
    },
    {
      "topico": "Variáveis que mudam a quantidade de óleo na água produzida",
      "conteudo": "Os trechos citam que a quantidade de óleo presente na água produzida pode variar com pH, salinidade, temperatura, razão óleo-água e tipo e quantidade de produtos químicos adicionados durante a produção."
    },
    {
      "topico": "Variabilidade entre campos, ativos e perfis de produção",
      "conteudo": "A composição da água produzida depende das características e da profundidade do campo produtor e pode variar entre ativos distintos. Também foram citadas diferenças relevantes entre plataformas produtoras de óleo e plataformas predominantemente de gás."
    },
    {
      "topico": "Consequência técnica da mudança de matriz",
      "conteudo": "Mudanças de composição alteram a distribuição do óleo na fase aquosa e a composição inorgânica associada ao efluente. Por isso, desempenho de tratamento, resposta de instrumentos e comparação entre campanhas podem mudar quando a matriz da água muda."
    },
    {
      "topico": "Limite de transferibilidade",
      "conteudo": "Resultados e ajustes obtidos em um ativo ou período não devem ser transferidos automaticamente para outro sem validação local. Esse cuidado é compatível com a variabilidade composicional descrita nos trechos e não deve ser tratado como formalidade normativa universal, mas como cautela técnica."
    },
    {
      "topico": "Monitoramento on-line de TOG",
      "conteudo": "O monitoramento em linha de TOG é valorizado por fornecer resposta em tempo real, aumentar a capacidade de controle do processamento, reduzir custo de análises rotineiras, gerar banco de dados e apoiar ajuste ou projeto de plantas."
    },
    {
      "topico": "Tecnologias citadas para medição",
      "conteudo": "Entre as tecnologias mencionadas no contexto offshore aparecem fluorescência, espectrofotometria de infravermelho em linha e outras medições ópticas. Os métodos laboratoriais citados incluem gravimetria e espectrofotometria de infravermelho, conforme os métodos mencionados nos trechos."
    },
    {
      "topico": "Resultado experimental e seu limite",
      "conteudo": "Em avaliação experimental resumida, diferentes monitores apresentaram correlação satisfatória com análise laboratorial. Esse achado é relevante para uso operacional, mas não demonstra equivalência universal para qualquer instalação, qualquer tipo de água produzida ou qualquer exigência regulatória."
    },
    {
      "topico": "Papel prático do monitor on-line",
      "conteudo": "Na aplicação prática, o instrumento on-line tende a ser mais forte como ferramenta de tendência, alarme e ajuste operacional. Sua resposta pode depender da calibração, da composição do óleo, da presença de sólidos e bolhas e da correspondência entre o ponto medido e a corrente efetivamente descartada."
    },
    {
      "topico": "Relação entre monitor on-line e laboratório",
      "conteudo": "Monitor on-line e laboratório exercem papéis complementares: o primeiro favorece resposta rápida e acompanhamento operacional; o segundo sustenta referência analítica conforme o método utilizado. Os trechos não autorizam tratar correlação experimental como substituição universal do laboratório."
    },
    {
      "topico": "Conformidade do descarte como cadeia integrada",
      "conteudo": "A conformidade do descarte depende de uma cadeia integrada: tratamento, medição, registro, decisão operacional e gestão de correntes fora de especificação. Assim, a presença de um equipamento de separação, por si só, não garante enquadramento do descarte."
    },
    {
      "topico": "Gestão de correntes fora de especificação",
      "conteudo": "Em FPSOs, os trechos sustentam um caso em que água produzida fora de especificação era armazenada em tanque dedicado. Isso apoia a ideia de que correntes offspec podem ser segregadas para evitar descarte direto enquanto a condição é corrigida, mas esse exemplo não deve ser convertido em requisito universal."
    },
    {
      "topico": "Consequência de erro de classificação de corrente ou inventário",
      "conteudo": "Os trechos também apoiam um caso em que um tanque que recebia água produzida fora de especificação foi classificado como tanque de óleo, levando ao uso de referência de projeto incompatível com o fluido real. Isso mostra que classificação incorreta de corrente ou inventário pode comprometer projeto, operação e resposta a desvios, embora o efeito concreto dependa do caso."
    },
    {
      "topico": "Comunicação e não conformidade",
      "conteudo": "Para o escopo regulatório citado, há previsão de comunicação imediata ao órgão ambiental quando houver descarte acima do valor máximo diário e de relatório de não conformidade quando a média mensal ficar acima do limite aplicável. Os números apagados nos trechos não podem ser reconstruídos."
    }
  ],
  "conceitos_chave": [
    {
      "termo": "Água produzida",
      "definicao": "Corrente aquosa separada do petróleo e do gás no processamento primário, ainda contendo diferentes constituintes dissolvidos, dispersos e em suspensão."
    },
    {
      "termo": "TOG",
      "definicao": "Teor de óleos e graxas usado como parâmetro central de controle do descarte contínuo offshore no escopo regulatório brasileiro citado."
    },
    {
      "termo": "Óleo disperso",
      "definicao": "Parcela do material orgânico presente como gotículas na fase aquosa, com comportamento de separação distinto do óleo dissolvido."
    },
    {
      "termo": "Óleo dissolvido",
      "definicao": "Parcela do material orgânico presente em solução na água produzida, com implicações diferentes para medição e tratamento."
    },
    {
      "termo": "Corrente offspec",
      "definicao": "Corrente fora de especificação, cuja gestão pode incluir segregação temporária para evitar descarte direto enquanto a condição operacional é corrigida."
    },
    {
      "termo": "Monitoramento on-line",
      "definicao": "Medição em tempo real útil para tendência, alarme e ajuste operacional, sem equivalência universal presumida com o laboratório."
    }
  ],
  "relacoes_importantes": [
    {
      "relacao": "Forma de ocorrência do óleo -> facilidade de remoção",
      "explicacao": "Óleo em gotas mais facilmente separáveis tende a responder melhor a processos físicos; óleo finamente disperso, emulsificado ou associado a sólidos tende a dificultar a remoção."
    },
    {
      "relacao": "Mudança de matriz -> mudança de desempenho e medição",
      "explicacao": "Variações de salinidade, temperatura, pH, razão óleo-água e química de processo podem alterar tanto a eficiência do tratamento quanto a resposta instrumental."
    },
    {
      "relacao": "Tratamento + medição + registro + decisão -> conformidade",
      "explicacao": "O atendimento ao descarte não depende só do tratamento físico-químico, mas de toda a cadeia de controle."
    },
    {
      "relacao": "Correlação experimental monitor-laboratório -> utilidade operacional, não equivalência universal",
      "explicacao": "A correlação observada em ensaio resumido sustenta uso operacional, mas não autoriza generalização irrestrita."
    },
    {
      "relacao": "Classificação incorreta do fluido -> risco para projeto e operação",
      "explicacao": "Usar referência de projeto incompatível com o fluido real armazenado pode comprometer arranjo operacional e resposta a desvios."
    }
  ],
  "limites_e_cautelas": [
    "Os trechos regulatórios citados tratam de descarte contínuo em plataformas marítimas; não devem ser extrapolados automaticamente para onshore.",
    "Números apagados com marcador <NUMBER> não podem ser reconstruídos.",
    "Correlação satisfatória entre monitor on-line e laboratório não equivale a equivalência analítica universal.",
    "O caso de armazenamento de água offspec em tanque dedicado é exemplo operacional específico, não obrigação geral.",
    "A afirmação de que hidrociclones podem, em alguns casos, bastar para enquadramento do efluente não foi acompanhada, nos trechos disponíveis, de critérios operacionais detalhados.",
    "Diferenças entre ativos, campos e períodos exigem validação local antes de transferir ajustes, calibrações ou conclusões."
  ],
